create table RB_BUS_AGREEMENT (RB_BUS_AGREEMENT_TYPE VARCHAR(10) not null  ,AGREEMENT_CLASS VARCHAR(10) null  ,PROD_NO VARCHAR(20) null  ,AGREEMENT_KEY_TYPE VARCHAR(20) null  ,AGREEMENT_AMT DECIMAL(17,2) null  ,AGREEMENT_KEY VARCHAR(30) null  ,CLIENT_NO VARCHAR(22) not null  ,AGREEMENT_OPEN_DATE TIMESTAMP(3) null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  ,END_DATE TIMESTAMP(3) not null  ,ACCT_CCY VARCHAR(3) null  ,SIGN_DATE TIMESTAMP(3) null  ,OUT_SIGN_DATE TIMESTAMP(3) null  ,AGREEMENT_ID VARCHAR(50) not null  ,AGRE_PROD_NO VARCHAR(20) null  ,CLIENT_SHORT VARCHAR(100) null  ,OUT_SIGN_USER_ID VARCHAR(30) null  ,SIGN_CHANNEL VARCHAR(10) null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,BASE_ACCT_NO VARCHAR(50) null  ,OUT_SIGN_CHANNEL VARCHAR(10) null  ,START_DATE TIMESTAMP(3) not null  ,SIGN_BRANCH VARCHAR(30) null  ,OUT_SIGN_BRANCH VARCHAR(30) null  ,AGREEMENT_SIGN_EFFECT_STATUS VARCHAR(3) null  ,TRAN_BRANCH VARCHAR(30) null  ,AGREEMENT_CLOSE_ACCT_FLAG VARCHAR(1) null  ,GREEMENT_SIGN_STATUS VARCHAR(3) null  ,ACCT_NAME VARCHAR(100) null  ,ACCT_SEQ_NO VARCHAR(5) null  ,SIGN_USER_ID VARCHAR(30) null  , primary key(AGREEMENT_ID));